mapper.select:
SELECT STRFTIME('%Y-%m-%d %H:%M:%S', S.CREATED_AT) AS createdAt, S.USER_NO AS userNo, U.ID AS userId, U.NICKNAME AS userNickname, S.FRAGMENT_NO AS fragmentNo, SUBSTR(F.CONTENT, 1, 80) AS fragmentContent FROM MB_FRAGMENT_SCRAP S INNER JOIN MB_USER U ON U.USER_NO = S.USER_NO INNER JOIN MB_FRAGMENT F ON F.FRAGMENT_NO = S.FRAGMENT_NO WHERE STRFTIME('%Y-%m-%d', S.CREATED_AT) = #{date}
AND ( UPPER(U.ID) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.NICKNAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(F.CONTENT) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY S.CREATED_AT DESC LIMIT 20 OFFSET #{offset}
